cat > /tmp/usage_agg.py <<'EOF'
import json, glob, os, datetime, collections

files = glob.glob('/home/ubuntu/.claude/projects/*/*.jsonl')
seen = {}
rows = []
for f in files:
    try:
        with open(f, 'r', errors='replace') as fh:
            for line in fh:
                if '"usage"' not in line:
                    continue
                try:
                    d = json.loads(line)
                except Exception:
                    continue
                if not isinstance(d, dict):
                    continue
                msg = d.get('message') or {}
                u = msg.get('usage')
                if not isinstance(u, dict):
                    continue
                mid = msg.get('id') or d.get('requestId') or d.get('uuid')
                ts = d.get('timestamp')
                if not ts:
                    continue
                key = (mid, ts, u.get('input_tokens'), u.get('output_tokens'))
                # dedupe identical usage records (same message written twice)
                k2 = mid if mid else key
                if k2 in seen:
                    continue
                seen[k2] = True
                rows.append({
                    'ts': ts,
                    'proj': os.path.basename(os.path.dirname(f)),
                    'session': os.path.basename(f).replace('.jsonl','')[:8],
                    'side': d.get('isSidechain', False),
                    'model': msg.get('model'),
                    'in': u.get('input_tokens', 0) or 0,
                    'cache_w': u.get('cache_creation_input_tokens', 0) or 0,
                    'cache_r': u.get('cache_read_input_tokens', 0) or 0,
                    'out': u.get('output_tokens', 0) or 0,
                })
    except Exception as e:
        print('ERR', f, e)

print('total records:', len(rows))
if rows:
    print('range:', min(r['ts'] for r in rows), '->', max(r['ts'] for r in rows))
json.dump(rows, open('/tmp/usage_rows.json','w'))
EOF
python3 /tmp/usage_agg.py

