     * @return true 注册成功，false 失败（通常是 conn 为空）
     */
    bool register_on_connection(DBusConnection* conn);

    // ---------- 方法实现（供静态分发函数调用） ----------

    // 基础查询方法
    bool handleListInterfaces(DBusConnection* conn, DBusMessage* msg);       ///< ListInterfaces: 返回网卡名数组
